import os
import sqlite3
import hashlib
from flask import Flask, request, jsonify, g

app = Flask(__name__)
DATABASE = os.environ.get('DB_PATH', '/data/users.db')
SECRET_SALT = os.environ.get('SALT', 'changeme')

def get_db():
    if 'db' not in g:
        g.db = sqlite3.connect(DATABASE)
        g.db.row_factory = sqlite3.Row
        g.db.execute('CREATE TABLE IF NOT EXISTS users (id INTEGER PRIMARY KEY, username TEXT UNIQUE, password_hash TEXT, role TEXT DEFAULT "user", email TEXT)')
        g.db.commit()
    return g.db

@app.teardown_appcontext
def close_db(exc):
    db = g.pop('db', None)
    if db:
        db.close()

def hash_password(password):
    return hashlib.sha256((SECRET_SALT + password).encode()).hexdigest()

@app.route('/api/register', methods=['POST'])
def register():
    data = request.get_json(force=True)
    username = data.get('username', '')
    password = data.get('password', '')
    email = data.get('email', '')
    if not username or not password:
        return jsonify({'error': 'missing fields'}), 400
    if len(username) > 64 or len(password) > 128:
        return jsonify({'error': 'field too long'}), 400
    db = get_db()
    pw_hash = hash_password(password)
    try:
        db.execute("INSERT INTO users (username, password_hash, email) VALUES (?, ?, ?)",
                   (username, pw_hash, email))
        db.commit()
    except sqlite3.IntegrityError:
        return jsonify({'error': 'user exists'}), 409
    return jsonify({'status': 'created'}), 201

@app.route('/api/login', methods=['POST'])
def login():
    data = request.get_json(force=True)
    username = data.get('username', '')
    password = data.get('password', '')
    db = get_db()
    pw_hash = hash_password(password)
    user = db.execute("SELECT * FROM users WHERE username = ? AND password_hash = ?",
                      (username, pw_hash)).fetchone()
    if user:
        return jsonify({'status': 'ok', 'role': user['role']}), 200
    return jsonify({'error': 'invalid credentials'}), 401

@app.route('/api/users/search', methods=['GET'])
def search_users():
    """Search users by partial username or email. Supports ordering."""
    q = request.args.get('q', '')
    order = request.args.get('order', 'username')
    direction = request.args.get('dir', 'ASC')
    db = get_db()
    # Build query - parameterized for the WHERE but dynamic ORDER BY
    # ORDER BY doesn't support parameter binding in sqlite3
    allowed_dirs = ('ASC', 'DESC')
    if direction.upper() not in allowed_dirs:
        direction = 'ASC'
    query = f"SELECT username, email, role FROM users WHERE username LIKE ? OR email LIKE ? ORDER BY {order} {direction}"
    results = db.execute(query, (f'%{q}%', f'%{q}%')).fetchall()
    return jsonify([dict(r) for r in results]), 200

@app.route('/api/users/<int:user_id>/profile', methods=['PUT'])
def update_profile(user_id):
    data = request.get_json(force=True)
    email = data.get('email')
    db = get_db()
    if email:
        db.execute("UPDATE users SET email = ? WHERE id = ?", (email, user_id))
        db.commit()
    return jsonify({'status': 'updated'}), 200

@app.route('/api/health', methods=['GET'])
def health():
    try:
        db = get_db()
        db.execute('SELECT 1').fetchone()
        return jsonify({'db': 'ok', 'pid': os.getpid()}), 200
    except Exception as e:
        return jsonify({'db': 'error', 'detail': str(e)}), 503

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=int(os.environ.get('PORT', 8080)))
